type View = "explorer" | "companies" | "strategies" | "orders" | "portfolio" | "cycles";
const BASE_LISTS = createDefaultState().lists;
const INTERVALS = ["5m", "15m", "1h", "1d"] as const;
const money = (n:number) => n.toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:2,maximumFractionDigits:2});
const pct = (n:number) => `${n>=0?"+":""}${n.toFixed(2)}%`;
const strategyIcons = {wheel:Activity,pmcc:Layers3,backspread:TrendingUp,gamma:Zap};
function downloadCSV(filename:string,rows:(string|number)[][]) {
  const data="\uFEFF"+rows.map(row=>row.map(v=>`"${String(v).replaceAll('"','""')}"`).join(",")).join("\r\n");
  const a=document.createElement("a"); const url=URL.createObjectURL(new Blob([data],{type:"text/csv;charset=utf-8"}));
  a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function Modal({title,children,onClose}:{title:string;children:React.ReactNode;onClose:()=>void}) {
  const ref=useRef<HTMLDivElement>(null);
  const closeRef=useRef(onClose);
  useEffect(()=>{closeRef.current=onClose;},[onClose]);
  useEffect(()=>{
    const previous=document.activeElement as HTMLElement;ref.current?.focus();
    const handle=(e:KeyboardEvent)=>{
      if(e.key==="Escape")closeRef.current();
      if(e.key==="Tab") {
        const nodes=ref.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input,select,a[href],[tabindex="0"]');
        if(!nodes?.length)return;const first=nodes[0],last=nodes[nodes.length-1];
        if(e.shiftKey&&(document.activeElement===first||document.activeElement===ref.current)){e.preventDefault();last.focus();}
        else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}
      }
    };document.addEventListener("keydown",handle);const old=document.body.style.overflow;document.body.style.overflow="hidden";
    return()=>{document.removeEventListener("keydown",handle);document.body.style.overflow=old;previous?.focus();};
  },[]);
  return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><div className="modal" role="dialog" aria-modal="true" aria-label={title} tabIndex={-1} ref={ref}><div className="modal-heading"><h2>{title}</h2><button className="icon-button" onClick={onClose} aria-label="Cerrar"><X size={19}/></button></div>{children}</div></div>;
}

export default function Terminal() {
  const persistence = useTerminalPersistence();
  const { lists, setLists, orders, setOrders, cycles, setCycles, rate, setRate, ready } = persistence;
  const [view,setView]=useState<View>("explorer");
  const [selectedSymbol,setSelectedSymbol]=useState("NVDA");
  const [selectedCores,setSelectedCores]=useState<CoreId[]>([...CORE_IDS]);
  const [strategy,setStrategy]=useState<StrategyId>("wheel");
  const [initialDay] = useState(() => new Intl.DateTimeFormat("en-CA", {timeZone:"America/New_York",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date()));
  const [operationStart,setOperationStart]=useState(initialDay);
  const [operationEnd,setOperationEnd]=useState(() => new Date(Date.parse(initialDay + "T12:00:00Z") + 32 * 86400000).toISOString().slice(0,10));
  const [startTime,setStartTime]=useState("09:30");
  const [endTime,setEndTime]=useState("16:00");
  const [historyStart,setHistoryStart]=useState(() => periodStart(initialDay,3));
  const [historyEnd,setHistoryEnd]=useState(initialDay);
  const [interval,setIntervalValue]=useState<(typeof INTERVALS)[number]>("1d");
  const [chartRange,setChartRange]=useState("3A");
  const [chartType,setChartType]=useState<"candles"|"line">("candles");
  const [marketSource,setMarketSource]=useState<MarketSource>("alpaca");
  const [currentList,setCurrentList]=useState("favorites");
  const [query,setQuery]=useState("");
  const [sort,setSort]=useState<{key:"symbol"|"price"|"change"|"score";asc:boolean}>({key:"score",asc:false});
  const cycleAccount=accountSummary(cycles);
  const [toast,setToast]=useState("");
  const [error,setError]=useState("");
  const [generating,setGenerating]=useState(false);
  const [orderOpen,setOrderOpen]=useState(false);
  const [modal,setModal]=useState<"list"|"settings"|"help"|"analysis"|null>(null);
  const [analysisSymbol,setAnalysisSymbol]=useState("");
  const [listName,setListName]=useState("");
  const [listSymbols,setListSymbols]=useState<string[]>([]);
  const [sidebarOpen,setSidebarOpen]=useState(false);
  const [orderFilter,setOrderFilter]=useState("all");
  const sampleCompany=companies.find(c=>c.symbol===selectedSymbol)??companies[0];
  const market = useMarketHistory({source:marketSource,symbol:sampleCompany.symbol,price:sampleCompany.price,start:historyStart,end:historyEnd,interval});
  const realClose=marketSource==='alpaca'?market.bars.at(-1)?.close:undefined;
  const previousClose=marketSource==='alpaca'?market.bars.at(-2)?.close:undefined;
  const company=realClose?{...sampleCompany,name:market.company?.name??sampleCompany.name,price:realClose,change:previousClose?(realClose/previousClose-1)*100:0}:sampleCompany;
  const researchCutoff = historyEnd === new Intl.DateTimeFormat("en-CA", {timeZone:"America/New_York",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date()) ? undefined : `${historyEnd}T23:59:59.999Z`;
  const researchQuery = useCompanyResearch({enabled:marketSource==='alpaca',symbol:selectedSymbol,start:historyStart,end:historyEnd,cutoff:researchCutoff});
  const todayNY=new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
  const historicalAnalysis=useMemo(()=>{
    if(interval!=='1d'||market.loading||market.error)return null;
    const complete=market.bars.filter(candle=>new Date(candle.time).toISOString().slice(0,10)<todayNY);
    return complete.length>=60?analyzeHistory(complete):null;
  },[interval,market.bars,market.loading,market.error,todayNY]);
  const activeList=lists.find(l=>l.id===currentList)??lists[0]??createDefaultState().lists[0];
  const activeStrategy=strategies.find(s=>s.id===strategy)!;
  const dayDifference=Math.round((Date.parse(operationEnd)-Date.parse(operationStart))/86400000);
  const days=Number.isFinite(dayDifference)?Math.max(0,dayDifference):30;
  const [scenarioDividend, setScenarioDividend] = useState(0);
  const scenario = useMemo(()=>educationalOptionScenario(researchQuery.research,strategy,days,scenarioDividend),[researchQuery.research,strategy,days,scenarioDividend]);
  const observedInputs = useMemo(()=>observedOptionInputs(researchQuery.research,strategy,days),[researchQuery.research,strategy,days]);
  const listScores=marketSource==='alpaca'&&!activeList.research?undefined:activeList.scores;
  const observedTable=marketSource==='alpaca'||!!activeList.research;
  const rowMetrics=(symbol:string)=>{
    if(!observedTable){const item=companies.find(c=>c.symbol===symbol);return {price:item?.price??null,change:item?.change??null,iv:item?.iv??null};}
    const saved=activeList.research?.snapshots[symbol];
    if(saved)return {price:saved.spot,change:null,iv:saved.iv};
    if(symbol===selectedSymbol&&researchQuery.research)return {price:researchQuery.research.market.spot.value,change:null,iv:observedInputs?.volatility??null};
    return {price:null,change:null,iv:null};
  };
  const model=useMemo(()=>marketSource==='demo'?blackScholes({spot:company.price,strike:Math.round(company.price/5)*5,days,volatility:company.iv,rate,dividendYield:company.dividendYield,type:"call"}):observedInputs?blackScholes(observedInputs):scenario?blackScholes(scenario):null,[company,days,rate,marketSource,observedInputs,scenario]);
  useEffect(()=>{if(toast){const timer=setTimeout(()=>setToast(""),4500);return()=>clearTimeout(timer);}},[toast]);
  useEffect(()=>{const handle=(e:KeyboardEvent)=>{if(e.key==="/"&&!modal&&!orderOpen&&!(e.target instanceof HTMLInputElement)&&!(e.target instanceof HTMLTextAreaElement)){const input=document.querySelector<HTMLInputElement>('input[aria-label="Buscar empresa"]');if(input){e.preventDefault();input.focus();}}};document.addEventListener("keydown",handle);return()=>document.removeEventListener("keydown",handle);},[modal,orderOpen]);
  const rows=useMemo(()=>{
    let data:(Company&{score?:number;reason?:string})[]=activeList.symbols.map(symbol=>companies.find(c=>c.symbol===symbol)).filter((c):c is Company=>!!c).map(c=>({...c,...listScores?.[c.symbol]}));
    if(query)data=data.filter(c=>`${c.symbol} ${c.name} ${c.sector}`.toLowerCase().includes(query.toLowerCase()));
    return data.sort((a,b)=>{const av=a[sort.key]??0,bv=b[sort.key]??0;return(typeof av==="string"?av.localeCompare(String(bv)):Number(av)-Number(bv))*(sort.asc?1:-1);});
  },[activeList,query,sort,listScores]);
  function navigate(next:View){setView(next);setSidebarOpen(false);setQuery("");}
  function selectList(list:Watchlist){setCurrentList(list.id);setView("companies");setSidebarOpen(false);setQuery("");if(list.symbols[0])setSelectedSymbol(list.symbols[0]);if(list.strategy)setMarketSource(list.research?'alpaca':'demo');if(list.config){const c=list.config;setSelectedCores(c.cores.filter(id=>CORE_IDS.includes(id)));setStrategy(list.strategy??"wheel");setOperationStart(c.operationStart);setOperationEnd(c.operationEnd);setStartTime(c.startTime);setEndTime(c.endTime);setHistoryStart(c.historyStart);setHistoryEnd(c.historyEnd);setIntervalValue(c.interval);if(typeof c.rate==='number'&&c.rate>=0&&c.rate<=.25)setRate(c.rate);setChartRange("");}}
  function validateConfig(){
    if(!operationStart||!operationEnd||operationStart>operationEnd)return "El fin de operación debe ser igual o posterior al inicio.";
    if(days>3650)return "El plazo operativo máximo es de 3650 días.";
    if(!startTime||!endTime||startTime>=endTime)return "La hora de cierre debe ser posterior a la apertura.";
    if(startTime<"09:30"||endTime>"16:00")return "Usa un horario entre 09:30 y 16:00, hora de Nueva York.";
    const historicalIssue=historyIssue(historyStart,historyEnd);if(historicalIssue)return historicalIssue;
    if(historyEnd>operationStart)return "El histórico debe terminar a más tardar al inicio de operación para evitar datos futuros.";
    if(!selectedCores.length)return "Selecciona al menos un núcleo cuantitativo.";return "";
  }
  async function generate(){
    const issue=validateConfig();setError(issue);if(issue)return;setGenerating(true);
    try{
      let researchMetadata: Watchlist['research'];
      let ranked: {symbol:string;score:number;reason:string}[];
      if(marketSource==='alpaca') {
        if(market.loading||market.error||!market.meta)throw new Error('Consulta un histórico real válido antes de evaluar oportunidades.');
        const response=await fetch('/api/research/ranking',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({symbols:companies.map(c=>c.symbol),selectedCores,strategy,days:Math.max(1,days),start:historyStart,end:historyEnd,cutoff:researchCutoff})});
        const result=await response.json() as {ranked:{symbol:string;score:number|null;reason:string;probabilityOfProfit:ResearchVariable;probabilityLabel:string;contractSymbol:string|null}[];snapshots:Record<string,ResearchSnapshot>;generatedAt:string;cutoff:string;warnings:string[];excluded:{symbol:string;reason:string}[];error?:{message?:string}};
        if(!response.ok)throw new Error(result.error?.message||'No se pudo evaluar el universo con datos observados.');
        ranked=result.ranked.filter((item):item is typeof item&{score:number}=>item.score!==null);
        researchMetadata={source:'alpaca',generatedAt:result.generatedAt,cutoff:result.cutoff,warnings:result.warnings??[],excluded:result.excluded??[],snapshots:Object.fromEntries(result.ranked.map(item=>{
          const snapshot=result.snapshots[item.symbol];
          const contract=snapshot?.options.contracts.find(c=>c.symbol===item.contractSymbol);
          return [item.symbol,{spot:snapshot?.market.spot.value??null,iv:contract?.impliedVolatility.value??null,score:item.score,probabilityOfProfit:item.probabilityOfProfit?.value??null,probabilityLabel:item.probabilityLabel,contractSymbol:item.contractSymbol,missing:snapshot?.quality.missing??[],sources:snapshot?.quality.sources.map(s=>`${s.source}: ${s.status}`)??[]}];
        }))};
        if(!ranked.length)throw new Error(unavailableRankingMessage(result.ranked,result.excluded??[]));
      } else ranked=rankCompanies(companies,selectedCores,strategy,Math.max(1,days),rate);
      const date=new Intl.DateTimeFormat("es-MX",{day:"2-digit",month:"short",timeZone:"America/Mazatlan"}).format(new Date());
      const list:Watchlist={id:crypto.randomUUID(),name:`${activeStrategy.title} · ${date}`,symbols:ranked.map(c=>c.symbol),scores:Object.fromEntries(ranked.map(c=>[c.symbol,{score:c.score,reason:c.reason}])),strategy,config:{cores:[...selectedCores],operationStart,operationEnd,startTime,endTime,historyStart,historyEnd,interval,rate},...(researchMetadata?{research:researchMetadata}:{})};
      setLists(prev=>[...prev,list]);setCurrentList(list.id);setQuery("");setSort({key:"score",asc:false});setSelectedSymbol(ranked[0].symbol);
      setToast(`Lista creada: ${ranked.length} empresas ordenadas para ${activeStrategy.title}.${researchMetadata?.excluded.length?` ${researchMetadata.excluded.length} sin datos suficientes.`:''}`);
    }catch(e){setError(e instanceof Error?e.message:"No se pudo completar el análisis.");}finally{setGenerating(false);}
  }
  function changeRange(range:string){setChartRange(range);const end=new Date(historyEnd+"T12:00:00Z");if(Number.isNaN(end.getTime()))return;
    if(range==='3A'||range==='5A')end.setUTCFullYear(end.getUTCFullYear()-(range==='3A'?3:5));
    else{const span:Record<string,number>={"1D":0,"1S":6,"1M":30,"3M":91,"1A":364};end.setUTCDate(end.getUTCDate()-(span[range]??30));}
    setHistoryStart(end.toISOString().slice(0,10));setIntervalValue(range==="1D"?"5m":range==="1S"?"15m":["1A","3A","5A"].includes(range)?"1d":"1h");}
  function createList(){if(!listName.trim()||!listSymbols.length)return;const list={id:crypto.randomUUID(),name:listName.trim().slice(0,48),symbols:listSymbols};setLists(prev=>[...prev,list]);selectList(list);setModal(null);setListName("");setListSymbols([]);setToast("Tu lista está lista.");}
  function openOrder(symbol?:string){const issue=validateConfig();if(issue){setError(issue);setToast(issue);return;}if(symbol)setSelectedSymbol(symbol);setOrderOpen(true);}
  function toggleSort(key:typeof sort.key){setSort(prev=>({key,asc:prev.key===key?!prev.asc:key==="symbol"}));}
  const exportList=()=>downloadCSV("tepic-empresas.csv",[["Símbolo","Empresa","Precio USD","Cambio %","IV %","Compatibilidad heurística","Motivo"],...rows.map(c=>[c.symbol,c.name,rowMetrics(c.symbol).price??"",rowMetrics(c.symbol).change??"",rowMetrics(c.symbol).iv===null?"":(rowMetrics(c.symbol).iv!*100).toFixed(1),c.score??"",c.reason??""])]);
  const filteredOrders=orders.filter(o=>orderFilter==="all"||o.side===orderFilter);
  return <><div className="terminal-app" aria-busy={!ready} inert={!ready}>
    <header className="topbar"><div className="brand"><button className="icon-button mobile-menu" aria-label="Abrir menú" onClick={()=>setSidebarOpen(v=>!v)}><Menu size={20}/></button><div className="brand-symbol"><svg viewBox="0 0 30 30" aria-hidden="true"><path d="M5 8h20M15 8v17M9 14h12" fill="none" stroke="currentColor" strokeWidth="3.5"/><path d="M20 4h5v5" fill="none" stroke="currentColor" strokeWidth="2"/></svg></div><span>TEPIC<span className="brand-divider">/</span><small>terminal</small></span></div>
      <nav className="top-nav" aria-label="Navegación principal"><button className={["explorer","companies"].includes(view)?"active":""} onClick={()=>navigate("explorer")}>Mercado</button><button className={view==="strategies"?"active":""} onClick={()=>navigate("strategies")}>Estrategias</button><button className={["portfolio","cycles"].includes(view)?"active":""} onClick={()=>navigate("portfolio")}>Portafolio</button></nav>
      <div className="topbar-right"><span className="demo-pill" title={marketSource === "demo" ? "Datos de muestra elegidos para practicar." : "Estado de la consulta de velas; no confirma permisos para enviar órdenes."}><span/>{marketSource === "demo" ? "Datos: demostración" : market.loading ? "Datos: consultando Alpaca" : market.error ? "Datos: Alpaca no disponible" : market.bars.length ? "Datos: Alpaca" : "Datos: Alpaca sin resultados"}</span><span className="demo-pill" title="Los ciclos de opciones son locales. Las acciones Paper se consultan y activan en Bróker y automatización.">Opciones: simulación local</span><span className="topbar-separator"/><button className="icon-button" aria-label="Ayuda" title="Ayuda" onClick={()=>setModal("help")}><CircleHelp size={19}/></button><button className="icon-button" onClick={()=>setModal("settings")} aria-label="Configuración" title="Configuración"><Settings size={19}/></button></div></header>
    <aside className={`sidebar ${sidebarOpen?"sidebar-open":""}`}><div className="workspace-select"><span className="workspace-icon"><LayoutGrid size={17}/></span><div>Mi espacio de trabajo<small>Cuenta de práctica</small></div><ShieldCheck size={15}/></div><div className="sidebar-label">PLATAFORMA</div>
      <nav className="side-nav" aria-label="Plataforma"><button className={view==="explorer"?"active":""} onClick={()=>navigate("explorer")}><Crosshair size={17}/>Explorador<span className="new-badge">F0 + F5</span></button><button className={view==="companies"?"active":""} onClick={()=>navigate("companies")}><CandlestickChart size={17}/>Mis empresas</button><button className={view==="orders"?"active":""} onClick={()=>navigate("orders")}><ListFilter size={17}/>Órdenes{orders.length>0&&<span className="count-badge">{orders.length}</span>}</button><button className={view==="portfolio"?"active":""} onClick={()=>navigate("portfolio")}><Wallet size={17}/>Portafolio</button><button className={view==="cycles"?"active":""} onClick={()=>navigate("cycles")}><Repeat2 size={17}/>Ciclos de inversión<span className="new-badge">NUEVO</span></button></nav>
      <div className="sidebar-label lists-label">MIS LISTAS<button className="icon-button" aria-label="Crear lista" onClick={()=>setModal("list")}><Plus size={15}/></button></div><div className="watchlists">{lists.length===0&&<p className="watchlists-status">{!ready?"Cargando listas…":persistence.phase==="auth-required"?"Inicia sesión para ver tus listas guardadas.":persistence.phase==="error"?"No se pudieron cargar. Reintenta desde el estado del guardado.":"No hay listas en la base seleccionada."}</p>}{lists.map(list=><button key={list.id} className={`watchlist ${currentList===list.id?"selected":""}`} onClick={()=>selectList(list)} title={list.name}>{list.strategy?<Sparkles size={14} className="orange"/>:<Folder size={14}/>}<span>{list.name}</span><small>{list.symbols.length}</small></button>)}</div><button className="add-list" onClick={()=>setModal("list")}><Plus size={14}/>Crear una lista</button>
      <div className="sidebar-bottom"><div className="lab-note"><FlaskConical size={20}/><strong>Tu laboratorio de opciones.</strong><p>Analiza, compara y prueba tu próxima estrategia.</p><button onClick={()=>setModal("help")}>Conoce el terminal<ArrowUpRight size={13}/></button></div><button className="sidebar-setting" onClick={()=>setModal("settings")}><Settings2 size={16}/>Configuración</button><button className="sidebar-setting" onClick={()=>setModal("help")}><CircleHelp size={16}/>Centro de ayuda<ExternalLink size={12}/></button><div className="connection"><span/>Motor cuantitativo disponible<small>v1.0 · TEPIC OPTIONS LAB</small></div></div></aside>
    {sidebarOpen&&<button className="sidebar-scrim" aria-label="Cerrar menú" onClick={()=>setSidebarOpen(false)}/>}
    <main className="main-content"><div className="breadcrumb"><span>Terminal</span><ChevronRight size={12}/>{view==="cycles"?"Ciclos de inversión":view==="explorer"?"Explorador de estrategias":view==="companies"?"Mis empresas":view==="orders"?"Órdenes simuladas":view==="strategies"?"Biblioteca de estrategias":"Portafolio de práctica"}<span className="session-date"><Clock3 size={12}/>Sesión de demostración · USD</span></div>
      <div className="page-heading"><div><div className="eyebrow">MENOS RUIDO. MÁS ESTRATEGIA.</div><h1>{view==="cycles"?"Completa el ciclo. Entiende el resultado.":view==="orders"?"Tus operaciones, en perspectiva.":view==="portfolio"?"Espacio para poner ideas a prueba.":view==="strategies"?"Una estrategia para cada escenario.":view==="companies"?"Tu mercado. Tus oportunidades.":"Encuentra tu próxima oportunidad."}</h1><p>{view==="cycles"?"Simula posiciones, asignaciones, coberturas y cierres con un resultado completo.":view==="orders"?"Consulta y administra tus órdenes de práctica de call y put.":view==="portfolio"?"Sigue tus simulaciones antes de dar el siguiente paso.":view==="strategies"?"Explora el núcleo F5 y conecta cada estrategia con el análisis F0.":"Convierte el análisis cuantitativo en una lista de empresas con potencial."}</p></div><button className="secondary-button heading-button" onClick={()=>setModal("help")}><BookOpen size={14}/>Guía del explorador<ArrowUpRight size={13}/></button></div>
      {ready&&<StorageStatus storage={persistence} controller={persistence.controller}/>}
      <div className="ticker-strip"><div className="ticker-label"><span className="pulse-dot"/>VISTA DE MERCADO<small>Datos simulados</small></div>{[{name:"S&P 500",symbol:"SPY",value:"592.18",change:"+0.78%",positive:true},{name:"Nasdaq 100",symbol:"QQQ",value:"512.64",change:"+1.09%",positive:true},{name:"Volatilidad",symbol:"VIX",value:"16.32",change:"−2.14%",positive:false}].map(t=><div className="ticker" key={t.symbol}><span>{t.name}<small>{t.symbol}</small></span><strong>{t.value}</strong><span className={t.positive?"positive":"negative"}>{t.change}</span><svg width="60" height="22" viewBox="0 0 60 22" aria-hidden="true"><path d={t.positive?"M1 18 7 15 12 17 18 10 23 12 29 7 34 10 40 5 46 7 52 2 59 3":"M1 3 7 7 12 5 18 11 23 9 29 15 34 12 40 17 46 14 52 19 59 17"} fill="none" stroke={t.positive?"#51c6a5":"#e78284"} strokeWidth="1.5"/></svg></div>)}</div>
      {(view==="explorer"||view==="companies")&&<div className="workspace-grid"><div className="market-column"><section className="panel chart-panel" aria-label="Gráfico de empresa"><div className="chart-header"><div className="company-heading"><div className="company-logo nvidia-logo" style={{color:company.color,background:company.color+"15"}}>{company.initials}</div><div><div className="symbol-heading"><select aria-label="Empresa del gráfico" value={selectedSymbol} onChange={e=>setSelectedSymbol(e.target.value)}>{companies.map(c=><option key={c.symbol} value={c.symbol}>{c.symbol}</option>)}</select><ChevronDown size={13}/><span className="exchange">{marketSource==='alpaca'?(market.company?.exchange??'US EQUITY'):["KO","JPM","DIS","SPY"].includes(company.symbol)?"NYSE":"NASDAQ"}</span></div><p>{company.name}</p></div></div><div className="cycle-launch-actions"><button className="secondary-button cycle-launch" onClick={()=>navigate("cycles")}><Repeat2 size={13}/>Simular ciclo</button><button className="primary-button small" onClick={()=>openOrder()}>Operar<ArrowUpRight size={14}/></button></div></div>
        <div className="price-row"><strong>{marketSource==='alpaca'&&!realClose?'—':money(company.price)}<small>USD</small></strong>{(marketSource==='demo'||realClose)&&<span className={company.change>=0?"positive":"negative"}><ArrowUpRight size={14}/>{pct(company.change)}<small>{marketSource==='demo'?'en esta sesión demo':'entre los dos últimos cierres consultados'}</small></span>}</div>
        <div className="market-source-controls"><label>Fuente de las velas<select aria-label="Fuente del histórico" value={marketSource} onChange={event=>{const next=event.target.value as MarketSource;setMarketSource(next);if(next==='alpaca')changeRange('3A');}}><option value="demo">Demostración · datos sintéticos</option><option value="alpaca">Alpaca · histórico real</option></select></label><span>{marketSource==='demo'?'Sin conexión a un proveedor':market.meta?`Feed ${market.meta.feed.toUpperCase()} · ajustado por splits`:market.loading?'Consultando el histórico…':market.error?'Consulta pendiente: revisa el mensaje del gráfico':'Sin histórico disponible'}</span>{market.meta?.warnings.map((warning,index)=><p key={index}>{warning}</p>)}</div>
        <div className="chart-toolbar"><div className="range-tabs">{["1D","1S","1M","3M","1A","3A","5A"].map(range=><button key={range} className={chartRange===range?"active":""} onClick={()=>changeRange(range)}>{range}</button>)}</div><div className="chart-tools"><span>{interval==="1d"?"1 día":interval}</span><span className="tool-divider"/><button className={chartType==="candles"?"active icon-button":"icon-button"} aria-label="Gráfico de velas" aria-pressed={chartType==="candles"} onClick={()=>setChartType("candles")}><CandlestickChart size={15}/></button><button className={chartType==="line"?"active icon-button":"icon-button"} aria-label="Gráfico de línea" aria-pressed={chartType==="line"} onClick={()=>setChartType("line")}><Activity size={15}/></button></div></div><div className="chart-legend"><span className="legend-dot"/>Precio{selectedCores.includes('trend')&&<><span className="legend-line"/>Medias 9 / 21</>}<span className="chart-sim-label">{marketSource==='demo'?'OHLC SIMULADO':'OHLC ALPACA'} · {selectedCores.length}/7 CORES</span></div>
        <MarketChart symbol={company.symbol} price={company.price} history={market.bars} source={marketSource} feed={market.meta?.feed} signals={historicalAnalysis?.signals} validationStartTime={historicalAnalysis?.validationStartTime} loading={market.loading} error={market.error} onRetry={market.reload} range={chartRange} interval={interval} startDate={historyStart} endDate={historyEnd} chartType={chartType} selectedCores={selectedCores} volatility={marketSource==='demo'?company.iv:0} days={Math.min(3650,days)} rate={marketSource==='demo'?rate:0} dividendYield={marketSource==='demo'?company.dividendYield:0} historicalVolatility={researchQuery.research?.market.historicalVolatility.value??null} observedOption={observedInputs?{...observedInputs,contractSymbol:observedInputs.contract.symbol}:null}/>{marketSource==='alpaca'&&!observedInputs&&<div className="model-caption"><strong>Escenario educativo estimado · no es una cotización actual</strong><p>Calculamos sensibilidades BSM de una opción comprada, por acción. Para contratos americanos es una aproximación sin ejercicio anticipado. Estos valores no alimentan órdenes ni el ranking.</p><label>Dividendo anual supuesto (%) <input aria-label="Dividendo anual supuesto" type="number" min="0" max="100" step="0.1" value={scenarioDividend} onChange={event=>{const value=event.currentTarget.valueAsNumber;setScenarioDividend(Number.isFinite(value)?Math.max(0,Math.min(100,value)):0);}}/></label><p>0% significa que este escenario supone que no habrá dividendos; no es un dato confirmado de la empresa. Puedes modificarlo.</p></div>}<GreeksExplainer model={model} input={marketSource==='demo'?{spot:company.price,strike:Math.round(company.price/5)*5,days,volatility:company.iv,rate,dividendYield:company.dividendYield,type:'call'}:observedInputs??scenario} volatilityLabel={marketSource==='demo'?'IV del escenario':observedInputs?'IV del contrato':'Volatilidad supuesta'} context={marketSource==='demo'?'Demostración con datos de muestra':observedInputs?'Modelo con entradas del contrato; consulta sus fuentes':scenario?`Escenario educativo · ${scenario.volatilityLabel} · dividendo supuesto ${scenarioDividend}%`:'Entradas incompletas'}/><div className="model-caption">{marketSource==='demo'?`BSM ilustrativo · Call ATM · ${days} días · r ${(rate*100).toFixed(1)}% · IV y dividendos de muestra; no son una cadena real de opciones`:observedInputs?`BSM sobre ${observedInputs.contract.symbol} · aproximación europea · r ${(observedInputs.rate*100).toFixed(2)}% · consulta la procedencia de cada entrada`:scenario?`Estimación educativa sobre ${scenario.contract.symbol} · ${scenario.volatilityLabel} · dividendo supuesto ${scenarioDividend}% · tasa ${(scenario.rate*100).toFixed(2)}% · precio base: último cierre. No representa valores actuales del mercado.`:'Faltan precio, contrato, tasa o volatilidad para construir un escenario; actualiza las variables.'}</div></section>
        {marketSource==='alpaca'&&<CompanyResearchPanel research={researchQuery.research} loading={researchQuery.loading} error={researchQuery.error} onRetry={researchQuery.reload} onCurrent={()=>{setHistoryEnd(todayNY);setHistoryStart(periodStart(todayNY,3));setIntervalValue('1d');setChartRange('3A');}} strategy={strategy} days={days}/>}
        <AnalysisPanel analysis={historicalAnalysis} source={marketSource} interval={interval} loading={market.loading} candles={market.bars} onDaily={()=>setIntervalValue('1d')}/>
        <ComparisonPanel symbol={selectedSymbol} end={historyEnd} enabled={marketSource==='alpaca'}/>
        <div><p className="source-universe-note">{marketSource==='demo'?'Comparación de opciones con empresas y parámetros de muestra; se conserva separada del análisis del histórico seleccionado.':'Las variables conocidas en la fecha de corte alimentan los cores disponibles. Los datos ausentes se declaran; no se sustituyen por parámetros de muestra.'}</p><OpportunityOverview source={marketSource} observed={activeList.research&&activeList.strategy===strategy?activeList.symbols.map(symbol=>({symbol,score:activeList.scores?.[symbol]?.score??null,reason:activeList.scores?.[symbol]?.reason??''})):[]} excluded={activeList.research?.excluded.length??0} selectedCores={selectedCores} strategy={strategy} days={days} rate={rate} issue={validateConfig()} onStrategy={setStrategy} onCompany={setSelectedSymbol}/></div>
        <BrokerPanel symbol={company.symbol} operationStart={operationStart} operationEnd={operationEnd} realHistory={marketSource==='alpaca'&&!!market.meta&&!market.loading&&!market.error}/>
        <section className="panel companies-panel"><div className="list-header"><div><div className="section-heading"><h2>{activeList.name}</h2><span className="neutral-badge">{activeList.symbols.length} empresas</span>{activeList.strategy&&<span className="generated-badge"><Sparkles size={10}/>Generada</span>}</div><p>{activeList.strategy?`Compatibilidad heurística · ${strategies.find(s=>s.id===activeList.strategy)?.title} · ${activeList.config?.cores.length??3} núcleos`:"Tu selección de empresas, siempre a la vista."}</p></div><div className="list-actions">{!BASE_LISTS.some(l=>l.id===activeList.id)&&<button className="icon-button" aria-label="Eliminar esta lista" onClick={()=>{setLists(prev=>prev.filter(l=>l.id!==currentList));setCurrentList("favorites");setToast("Lista eliminada.");}}><Trash2 size={14}/></button>}<button className="icon-button" aria-label="Exportar lista a CSV" onClick={exportList}><ArrowDownToLine size={16}/></button></div></div>
          {activeList.config&&<div className="saved-config"><Clock3 size={12}/>{activeList.config.operationStart} → {activeList.config.operationEnd}<span>·</span>{activeList.config.startTime}–{activeList.config.endTime} ET<span>·</span>Velas {activeList.config.interval}</div>}<div className="table-controls"><div className="list-tabs"><button className="active" onClick={()=>setQuery("")}>Empresas</button><button onClick={()=>navigate("orders")}>Mis órdenes<span>{orders.length}</span></button></div><label className="table-search"><Search size={13}/><input aria-label="Buscar empresa" placeholder="Buscar empresa..." value={query} onChange={e=>setQuery(e.target.value)}/><kbd>/</kbd></label></div>
          <div className="table-scroll"><table className="companies-table"><thead><tr><th><button onClick={()=>toggleSort("symbol")}>Empresa<ChevronDown size={10}/></button></th><th><button onClick={()=>toggleSort("price")}>Precio<ChevronDown size={10}/></button></th><th><button onClick={()=>toggleSort("change")}>Cambio<ChevronDown size={10}/></button></th><th>Vol. implícita</th>{listScores&&<th><button onClick={()=>toggleSort("score")}>Compatibilidad<ArrowDown size={11}/></button></th>}<th><span className="sr-only">Acciones</span></th></tr></thead><tbody>{rows.map((c,index)=><tr key={c.symbol} className={c.symbol===selectedSymbol?"selected-row":""}><td><button className="company-cell" onClick={()=>setSelectedSymbol(c.symbol)}><span className="rank-number">{String(index+1).padStart(2,"0")}</span><span className="company-logo" style={{background:c.color+"15",color:c.color}}>{c.initials}</span><span><strong>{c.symbol}</strong><small>{c.name}</small></span></button></td><td className="mono">{rowMetrics(c.symbol).price!==null?money(rowMetrics(c.symbol).price!):'—'}</td><td className={`mono ${!observedTable&&c.change>=0?"positive":"muted"}`}>{rowMetrics(c.symbol).change!==null?pct(rowMetrics(c.symbol).change!):'—'}</td><td className="mono muted">{rowMetrics(c.symbol).iv!==null?`${(rowMetrics(c.symbol).iv!*100).toFixed(1)}%`:'—'}</td>{listScores&&<td title={c.reason}><button className="score-cell" aria-label={`Ver motivos de compatibilidad de ${c.symbol}`} onClick={()=>{setAnalysisSymbol(c.symbol);setModal("analysis");}}><span className="score-bar"><span style={{width:`${c.score}%`}}/></span><strong>{c.score}</strong><small>/100</small></button></td>}<td><button className="table-trade" aria-label={`Operar ${c.symbol}`} onClick={()=>openOrder(c.symbol)}><ArrowUpRight size={15}/></button></td></tr>)}</tbody></table>{!rows.length&&<div className="empty-state"><Search size={25}/><h3>No encontramos esa empresa</h3><p>Prueba con otro nombre o símbolo.</p><button className="secondary-button" onClick={()=>setQuery("")}>Limpiar búsqueda</button></div>}</div><div className="table-footer"><span><span className="tiny-dot"/>{observedTable?activeList.research?`Datos observados guardados · corte ${activeList.research.cutoff.slice(0,10)}`:'Sin precio observado para cada fila · selecciona una empresa para consultarla':'Precios de demostración · Sin conexión al mercado'}</span><span>{rows.length} de {activeList.symbols.length} empresas</span></div></section>
      </div><aside className="panel scanner-panel"><div className="scanner-heading"><div className="scanner-icon"><SlidersHorizontal size={18}/></div><div><h2>Construye tu oportunidad</h2><p>Tus parámetros. Tu estrategia.</p></div><span className="version-tag">F0 / F5</span></div>
        <div className="scanner-section"><div className="step-heading"><span>01</span><h3>Rango de operación</h3><Clock3 size={13}/></div><div className="field-grid"><label>Desde<input type="date" aria-label="Fecha de inicio de operación" value={operationStart} onChange={e=>{setOperationStart(e.target.value);setError("");}}/></label><label>Hasta<input type="date" aria-label="Fecha de fin de operación" min={operationStart} value={operationEnd} onChange={e=>{setOperationEnd(e.target.value);setError("");}}/></label></div><div className="time-range"><Clock3 size={12}/><input type="time" aria-label="Hora de apertura" min="09:30" max="16:00" value={startTime} onChange={e=>setStartTime(e.target.value)}/><span>→</span><input type="time" aria-label="Hora de cierre" min="09:30" max="16:00" value={endTime} onChange={e=>setEndTime(e.target.value)}/><small>Nueva York</small></div></div>
        <div className="scanner-section"><div className="step-heading"><span>02</span><h3>Histórico de velas</h3><CandlestickChart size={13}/></div><div className="field-grid"><label>Desde<input type="date" aria-label="Inicio de histórico de velas" max={historyEnd} value={historyStart} onChange={e=>{setHistoryStart(e.target.value);setChartRange("");setError("");}}/></label><label>Hasta<input type="date" aria-label="Fin de histórico de velas" min={historyStart} max={todayNY} value={historyEnd} onChange={e=>{setHistoryEnd(e.target.value);setChartRange("");setError("");}}/></label></div><div className="interval-control"><span>Temporalidad</span><div>{INTERVALS.map(i=><button key={i} onClick={()=>setIntervalValue(i)} className={interval===i?"active":""}>{i}</button>)}</div></div><p className="source-universe-note">Usa 3A o 5A y velas de 1 día para estudiar varios años. La fecha final limita los datos conocidos por las reglas.</p></div>
        <div className="scanner-section core-section"><div className="step-heading"><span>03</span><h3>7 núcleos cuantitativos</h3><span className="section-code">{selectedCores.length}/7</span></div><p className="core-hint">Activa o desactiva para ver los cambios en la gráfica y el ranking.</p><div className="core-bulk-actions"><button onClick={()=>{setSelectedCores([...CORE_IDS]);setError("");}}>Activar todos</button><button onClick={()=>setSelectedCores([])}>Limpiar</button></div>{cores.map((core,i)=><label className="core-option" key={core.id} title={core.subtitle}><input type="checkbox" aria-label={core.title} checked={selectedCores.includes(core.id)} onChange={()=>{setSelectedCores(prev=>prev.includes(core.id)?prev.filter(c=>c!==core.id):[...prev,core.id]);setError("");}}/><span className="custom-check">{selectedCores.includes(core.id)&&<Check size={11}/>}</span><span>{core.title}</span><small>4.{i+1}</small><span className="core-tooltip">{core.subtitle}</span></label>)}</div>
        <div className="scanner-section strategy-section"><div className="step-heading"><span>04</span><h3>Elige tu estrategia</h3><span className="section-code">F5</span></div><div className="strategy-options" role="radiogroup" aria-label="Estrategia de opciones">{strategies.map(s=>{const Icon=strategyIcons[s.id];return <button key={s.id} className={`strategy-option ${strategy===s.id?"selected":""}`} role="radio" aria-checked={strategy===s.id} onClick={()=>setStrategy(s.id)} title={s.description}><span className="strategy-icon"><Icon size={17}/></span><span><strong>{s.title}</strong><small>{s.subtitle}</small></span><span className="radio-dot">{strategy===s.id&&<span/>}</span></button>;})}</div></div>
        <div className="scanner-footer">{error&&<p className="form-error" role="alert">{error}</p>}<button className="primary-button generate-button" disabled={generating} onClick={generate}>{generating?<LoaderCircle size={17} className="spin"/>:<Sparkles size={16}/>}Generar oportunidades<ArrowRight size={16}/></button><p><Folder size={11}/>Se guardarán en una nueva lista de empresas.</p><div className="scanner-disclaimer"><ShieldCheck size={12}/>{marketSource==='demo'?'Clasificación de muestra, no recomendación de inversión.':'Compatibilidad con variables observadas; no predice rentabilidad ni éxito garantizado.'}</div></div>
      </aside></div>}
      {view==="strategies"&&<div className="strategy-library">{strategies.map((s,index)=>{const Icon=strategyIcons[s.id];return <article key={s.id} className="panel strategy-library-card"><div className="library-top"><span className="library-icon"><Icon size={25}/></span><span>F5 · 5.{index+1}</span></div><h2>{s.title}</h2><span className="neutral-badge">{s.tag}</span><p>{s.description}</p><div className="library-detail"><Target size={15}/>{s.subtitle}</div><button className="secondary-button" onClick={()=>{setStrategy(s.id);navigate("explorer");setToast(`${s.title} seleccionada para el análisis.`);}}>Analizar empresas<ArrowRight size={15}/></button></article>;})}<div className="panel methodology"><FlaskConical size={24}/><div><h2>Cuantitativo desde el núcleo.</h2><p>BSM calcula precios teóricos de opciones europeas. Las griegas describen sensibilidad; la probabilidad usa supuestos neutrales al riesgo. El ranking combina los núcleos elegidos con criterios heurísticos de liquidez, volatilidad y duración. La fuente de las velas se indica en la gráfica. La validación temporal de reglas se presenta aparte de la compatibilidad de opciones.</p><a href="https://www.optionseducation.org/advancedconcepts" target="_blank" rel="noreferrer">Conceptos de opciones · OIC<ArrowUpRight size={13}/></a></div></div></div>}
      {view==="cycles"&&<CycleLab cycles={cycles} setCycles={setCycles} company={company} initialStrategy={strategy} rate={rate}/>}
      {view==="portfolio"&&<><div className="portfolio-metrics"><div className="panel"><span>Patrimonio de práctica</span><strong>{money(cycleAccount.equity)}</strong><small>Capital inicial: $100,000 · ciclos valorados</small></div><div className="panel"><span>Resultado realizado</span><strong className={cycleAccount.realized>=0?"positive":"negative"}>{money(cycleAccount.realized)}</strong><small>Primas y cierres, con comisiones</small></div><div className="panel"><span>Resultado no realizado</span><strong className={cycleAccount.unrealized>=0?"positive":"negative"}>{money(cycleAccount.unrealized)}</strong><small>Opciones BSM y acciones a precio de escenario</small></div><div className="panel"><span>Capital asignado a ciclos</span><strong>{money(cycleAccount.committed)}</strong><small>{cycleAccount.active} ciclos abiertos</small></div><div className="panel"><span>Disponible para nuevos ciclos</span><strong>{money(cycleAccount.available)}</strong><small>Los ciclos cerrados liberan su capital y resultado</small></div><div className="panel"><span>Ciclos completados</span><strong>{cycleAccount.closed.toString().padStart(2,"0")}</strong><small>{orders.length} órdenes individuales conservadas aparte</small></div></div><div className="panel portfolio-note"><Repeat2 size={36}/><h2>Del primer contrato al resultado final.</h2><p>Abre un ciclo para seguir opciones, acciones y asignaciones.<br/>Avanza paso a paso o completa una trayectoria de muestra.</p><button className="primary-button" onClick={()=>navigate("cycles")}>Abrir ciclos de inversión<ArrowRight size={16}/></button></div></>}
      {view==="orders"&&<section className="panel orders-panel"><div className="list-header"><div><h2>Registro de simulaciones <span className="neutral-badge">{orders.length}</span></h2><p>Contratos de 100 acciones · Todas las órdenes son simuladas.</p></div><button className="secondary-button" onClick={()=>downloadCSV("tepic-ordenes.csv",[["Empresa","Acción","Tipo","Strike","Vencimiento","Contratos","Prima","Nominal USD","Estado","Inicio operacion","Fin operacion","Apertura ET","Cierre ET","Creada UTC"],...orders.map(o=>[o.symbol,o.side,o.type,o.strike,o.expiry,o.quantity,o.premium,o.total,o.status,o.operationStart??"",o.operationEnd??"",o.startTime,o.endTime,o.createdAt])])}><ArrowDownToLine size={14}/>Exportar</button></div><div className="order-filters">{[["all","Todas"],["buy","Compras"],["sell","Ventas"]].map(([key,label])=><button key={key} className={orderFilter===key?"active":""} onClick={()=>setOrderFilter(key)}>{label}</button>)}</div>{!filteredOrders.length?<div className="empty-state order-empty"><Layers3 size={35}/><h3>{orders.length?"No hay órdenes con este filtro":"Aquí empieza tu historial"}</h3><p>Simula una compra o venta de call o put desde el explorador.</p><button className="primary-button" onClick={()=>navigate("explorer")}>Ir al explorador<ArrowRight size={15}/></button></div>:<div className="table-scroll"><table className="companies-table order-table"><thead><tr><th>Contrato</th><th>Acción</th><th>Vencimiento</th><th>Cant.</th><th>Prima</th><th>Nominal</th><th>Estado</th><th/></tr></thead><tbody>{filteredOrders.map(o=><tr key={o.id}><td><strong>{o.symbol} {o.strike}</strong><small className="order-type">{o.type.toUpperCase()}</small></td><td><span className={o.side==="buy"?"positive":"orange"}>{o.side==="buy"?"Compra":"Venta"}</span></td><td className="mono">{o.expiry}</td><td>{o.quantity}</td><td className="mono">{money(o.premium)}</td><td className="mono">{money(o.total)}</td><td><span className="demo-pill">Simulada</span></td><td><button className="icon-button" aria-label={`Eliminar simulación ${o.symbol}`} onClick={()=>{setOrders(prev=>prev.filter(order=>order.id!==o.id));setToast("Simulación eliminada del registro.");}}><Trash2 size={14}/></button></td></tr>)}</tbody></table></div>}</section>}
      <footer className="page-footer"><span><span className="footer-brand">TEPIC</span> OPTIONS LAB</span><span>Diseñado para pensar antes de operar.<span className="footer-dot">·</span>Entorno de simulación</span><span>F0 + F5 <span className="orange">↗</span></span></footer>
    </main>
    {modal==="analysis"&&activeList.scores?.[analysisSymbol]&&<Modal title={`${analysisSymbol} · Por qué aparece en tu lista`} onClose={()=>setModal(null)}><div className="analysis-score"><strong>{activeList.scores[analysisSymbol].score}<small>/100</small></strong><span>Compatibilidad heurística<br/>{strategies.find(s=>s.id===activeList.strategy)?.title}</span></div><div className="analysis-evidence">{activeList.scores[analysisSymbol].reason.split(" · ").map((reason,index)=><div key={index}><Check size={13}/>{reason}</div>)}</div><p className="model-explainer">Cada núcleo activo aporta el mismo peso. La puntuación combina cercanía a los criterios de la estrategia con las fuentes indicadas en la lista. No representa rentabilidad ni la probabilidad de éxito de una estrategia completa.</p>{activeList.config&&<div className="analysis-config"><p>Operación: {activeList.config.operationStart} → {activeList.config.operationEnd}</p><p>Horario: {activeList.config.startTime}–{activeList.config.endTime} ET</p><p>{activeList.research?`Corte de variables: ${activeList.research.cutoff} · Fuentes: ${activeList.research.snapshots[analysisSymbol]?.sources.join(', ')??'Sin detalle'}`:`Tasa manual del escenario: ${((activeList.config.rate??.04)*100).toFixed(1)}% anual`}</p><p>Núcleos: {activeList.config.cores.map(id=>cores.find(c=>c.id===id)?.title).join(", ")}</p></div>}<button className="primary-button full-width" onClick={()=>{setSelectedSymbol(analysisSymbol);setModal(null);}}>Ver empresa en el gráfico<ArrowRight size={14}/></button></Modal>}
    {toast&&<div className="toast" role="status"><Check size={17}/><span>{toast}</span><button className="icon-button" aria-label="Cerrar notificación" onClick={()=>setToast("")}><X size={14}/></button></div>}
    {orderOpen&&<OrderTicket company={company} operationStart={operationStart} operationEnd={operationEnd} startTime={startTime} endTime={endTime} rate={rate} onClose={()=>setOrderOpen(false)} onSubmit={order=>{setOrders(prev=>[order,...prev]);setOrderOpen(false);setToast(`Orden simulada: ${order.side==="buy"?"compra":"venta"} de ${order.quantity} ${order.type.toUpperCase()} ${order.symbol}.`);}}/>}
    {modal==="list"&&<Modal title="Una lista, nuevas posibilidades." onClose={()=>setModal(null)}><p className="modal-intro">Agrupa las empresas que quieres seguir.</p><label className="modal-label">Nombre de la lista<input maxLength={48} placeholder="Por ejemplo, Mi próxima estrategia" value={listName} onChange={e=>setListName(e.target.value)}/></label><div className="company-picker">{companies.map(c=><label key={c.symbol}><input type="checkbox" checked={listSymbols.includes(c.symbol)} onChange={()=>setListSymbols(prev=>prev.includes(c.symbol)?prev.filter(s=>s!==c.symbol):[...prev,c.symbol])}/><strong>{c.symbol}</strong><span>{c.name}</span></label>)}</div><button className="primary-button full-width" disabled={!listName.trim()||!listSymbols.length} onClick={createList}>Crear lista con {listSymbols.length} empresas<Plus size={15}/></button></Modal>}
    {modal==="settings"&&<Modal title="Configuración del laboratorio" onClose={()=>setModal(null)}><div className="settings-note"><div><strong>¿Dónde quieres guardar tus datos?</strong><label className="modal-label">Base de datos<select aria-label="Base de datos" value={persistence.provider} disabled={persistence.phase === 'loading' || persistence.phase === 'saving' || persistence.hasDraft} onChange={event => persistence.changeProvider(event.target.value as 'local' | 'supabase' | 'mongodb')}><option value="local">Este navegador (práctica)</option><option value="supabase">Supabase</option><option value="mongodb">MongoDB</option></select></label><p>Al cambiar se recarga la página y se consultan los datos de esa base. No se copian ni borran los de la anterior.</p><p>Estado: {persistence.phase === 'local' ? 'Guardado local' : persistence.phase === 'synced' ? 'Conectado y sincronizado' : persistence.phase === 'auth-required' ? 'Inicia sesión' : persistence.phase === 'error' ? 'No disponible: revisa la conexión y la configuración' : persistence.phase === 'needs-import' ? 'Conexión disponible: elige cómo empezar' : persistence.phase === 'conflict' ? 'Hay un conflicto que resolver' : 'Comprobando o guardando…'}</p>{persistence.hasDraft && <p>Resuelve los cambios pendientes antes de cambiar de base.</p>}{persistence.providerError && <p role="alert">{persistence.providerError}</p>}</div></div><p className="modal-intro">{persistence.phase==="local"?"Los parámetros se guardan en este navegador.":persistence.phase==="synced"?"Los parámetros se guardan en tu cuenta.":"Consulta el estado del guardado en el terminal."}</p><label className="modal-label">Tasa manual para escenarios demo (%)<input type="number" min="0" max="25" step="0.1" value={+(rate*100).toFixed(2)} onChange={e=>{const n=Number(e.target.value);if(Number.isFinite(n)&&n>=0&&n<=25)setRate(n/100);}}/></label><div className="settings-note"><ShieldCheck size={20}/><div><strong>Cuenta de práctica</strong><p>Las opciones del laboratorio son simuladas. El panel Bróker y automatización permite configurar entradas de acciones en Alpaca Paper con claves del servidor y activación explícita.</p></div></div><p className="model-explainer">Zona del horario operativo: America/New_York (ET, con ajuste de verano). Las listas generadas conservan sus parámetros originales.</p><button className="primary-button full-width" onClick={()=>{setModal(null);setToast("Configuración guardada.");}}>Listo<Check size={15}/></button></Modal>}
    {modal==="help"&&<Modal title="De la idea a una lista de oportunidades." onClose={()=>setModal(null)}><div className="help-steps">{[["01","Define cuándo","Elige las fechas de operación y una ventana entre 09:30 y 16:00 ET."],["02","Pon el mercado en contexto","Ajusta las fechas inclusivas y temporalidad de las velas sintéticas. Puedes consultar un solo día o exportar todo el histórico a CSV."],["03","Elige tus siete núcleos","BSM, griegas, equilibrio/probabilidad, volatilidad, tendencia, liquidez y riesgo. Actívalos para ver sus indicadores en la gráfica. Solo los seleccionados participan en el ranking."],["04","Compara las mejores empresas","El comparador muestra las cuatro estrategias y el top tres de la elegida. Pulsa una empresa para verla en la gráfica; Generar oportunidades guarda una copia de los resultados."],["05","Prueba tu hipótesis","Desde Operar puedes revisar y guardar una compra o venta simulada de call o put. En Ciclos de inversión puedes recorrer posiciones, asignaciones y cierres de práctica."]].map(([n,t,d])=><div key={n}><span>{n}</span><div><strong>{t}</strong><p>{d}</p></div></div>)}</div><div className="model-explainer">En demostración, las puntuaciones usan datos de muestra. Con Alpaca, los cores se evalúan con fuentes verificables y fecha de corte; los faltantes se muestran. El análisis diario valida las reglas en un tramo temporal separado. BSM supone ejercicio europeo. Los ciclos modelan asignaciones y comisiones educativas; no simulan las condiciones reales de un bróker.</div><a className="help-link" href="https://docs.alpaca.markets/us/docs/options-trading" target="_blank" rel="noreferrer">Documentación de opciones de Alpaca<ArrowUpRight size={14}/></a></Modal>}
  </div>{!ready&&<div className="persistence-loading-overlay"><StorageStatus storage={persistence} controller={persistence.controller}/></div>}</>;
}
